from pathlib import Path
import re
p=Path('_site/index.html')
s=p.read_text(encoding='utf-8')
MARK='OPTYKER_APPOINTMENTS_UI_V1'
if MARK in s: raise SystemExit(0)
if 'OPTYKER_WHATSAPP_CHANNEL_V2' not in s or 'id="navSettings"' not in s: raise SystemExit('Impostazioni Optyker non disponibili')

def add_head(x):
    global s
    i=s.find('</head>'); b=s.find('<body')
    if i<0 or (b>=0 and i>b): raise SystemExit('head non trovato')
    s=s[:i]+x+s[i:]

def add_body(x):
    global s
    i=s.rfind('</body>')
    if i<0: raise SystemExit('body non trovato')
    s=s[:i]+x+s[i:]

m=re.search(r'(<button\b[^>]*\bid=["\']navChat["\'][\s\S]*?</button>)',s,re.I)
if not m: raise SystemExit('Chat non trovata')
btn='<button id="navAppointments" class="moduleBtn" data-short="Agenda" type="button" onclick="optykerOpenAppointments()"><span class="winNavIcon" aria-hidden="true">▦</span><span>Agenda</span></button>'
s=s[:m.end()]+'\n    '+btn+s[m.end():]
anchor='  <div id="onlineOrdersPanel" class="panel">'
if anchor not in s: raise SystemExit('Ordini non trovati')
panel='''  <div id="optykerAppointmentsPanel" class="panel" style="display:none"><div class="oaHead"><div><div class="oaK">Ottica Visual Care</div><div class="oaTitle">Agenda appuntamenti</div><div id="oaRange" class="oaSub"></div></div><div class="oaActions"><button id="oaNew" class="primary" type="button">+ Nuovo appuntamento</button><button id="oaSettings" class="secondary" type="button">Impostazioni agenda</button></div></div><div class="oaToolbar"><button id="oaPrev" class="secondary">‹</button><button id="oaToday" class="secondary">Oggi</button><button id="oaNext" class="secondary">›</button><select id="oaOpFilter"><option value="">Tutti gli operatori</option></select><select id="oaStudioFilter"><option value="">Tutti gli studi</option></select><button id="oaReload" class="secondary">Aggiorna</button></div><div id="oaStatus" class="oaStatus"></div><div id="oaCalendar" class="oaCalendar"></div></div>\n'''
s=s.replace(anchor,panel+anchor,1)
